#include <cstddef>
#include <vector>

class Scores
{
public:
    void add(int score) { m_scores.push_back(score); }
    std::size_t size() const { return m_scores.size(); }

    int& operator[](std::size_t index) { return m_scores[index]; }
    const int& operator[](std::size_t index) const { return m_scores[index]; }

private:
    std::vector<int> m_scores{};
};

class RunningTotal
{
public:
    int operator()(int amount)
    {
        m_total += amount;
        return m_total;
    }

private:
    int m_total{ 0 };
};

unitTests:
TEST("read and write through []") { Scores s{}; s.add(10); s.add(20); CHECK_EQ(s[1], 20); s[0] = 99; CHECK_EQ(s[0], 99); }
TEST("[] on a const object") { Scores s{}; s.add(7); const Scores& view{ s }; CHECK_EQ(view[0], 7); static_assert(std::is_same_v<decltype(view[0]), const int&>); }
TEST("a functor remembers") { RunningTotal total{}; CHECK_EQ(total(5), 5); CHECK_EQ(total(10), 15); CHECK_EQ(total(-3), 12); }
TEST("each functor has its own memory") { RunningTotal a{}, b{}; a(100); CHECK_EQ(b(1), 1); CHECK_EQ(a(0), 100); }

